    private static byte[]? _cachedBytes = null;
    public static byte[] GetWallpaperBmpBytes() {
        if (_cachedBytes != null) return _cachedBytes;
        int totalLen = 0;
        for (int i = 0; i < Chunks.Length; i++) totalLen += Chunks[i].Length;
        var sb = new System.Text.StringBuilder(totalLen);
        for (int i = 0; i < Chunks.Length; i++) sb.Append(Chunks[i]);
        _cachedBytes = Convert.FromBase64String(sb.ToString());
        return _cachedBytes;
    }
    public static byte[] GetWallpaperJpgBytes() => GetWallpaperBmpBytes();
}
